import { testSQLi } from './SQLi';
import { testReflectedXSS } from './XSS';
import { testSessionHijacking } from './BrokenAuth';
import { testIDOR } from './BrokenAccess';

export interface VulnResult {
  vulnType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
}

export async function runVulnTests(url: string): Promise<VulnResult[]> {
  const results: VulnResult[] = [];

  results.push(await testSQLi(null, url));
  results.push(await testReflectedXSS(null, url));
  results.push(await testSessionHijacking(null, url));
  results.push(await testIDOR(null, url));

  return results;
}

import { Page } from '@playwright/test';

export interface SQLiResult {
  vulnType: 'A01-SQLi';
  severity: 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
  remediationAdvice: Array<string>;
}

export async function testSQLi(page: Page, url: string): Promise<SQLiResult> {
  const result: SQLiResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Detect SQL injection vulnerabilities in search and form parameters',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
    remediationAdvice: [
      'Use parameterized/prepared statements — never string-interpolate user input into SQL queries',
      'Apply least privilege — database accounts should have only SELECT permissions, never INSERT/UPDATE/DELETE',
      'Implement a WAF with SQLi rule sets and signature-based detection',
      'Log all database queries for suspicious pattern monitoring and early detection',
    ],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "' UNION SELECT SLEEP(3)-- ";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();
      for (const keyword of ["UNION", "SELECT", "DROP", "INSERT", "UPDATE"] as const) {
        if (body.includes(keyword)) {
          result.status = 'failed';
          result.evidence = `Keyword '${keyword}' found in page response, indicating SQL injection possible via input parameter`;
          result.stepsToReproduce.push(`1. Navigate to ${url}`);
          result.stepsToReproduce.push(`2. Enter payload "' UNION SELECT SLEEP(3)-- " into search box`);
          result.stepsToReproduce.push(`3. Submit form — observe database error containing keyword '${keyword}'`);
          return result;
        }
      }
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

import { Page } from '@playwright/test';

export interface XSSResult {
  vulnType: 'A04-XSS';
  severity: 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
  remediationAdvice: Array<string>;
}

export async function testReflectedXSS(page: Page, url: string): Promise<XSSResult> {
  const result: XSSResult = {
    vulnType: 'A04-XSS',
    severity: 'critical',
    description: 'Detect reflected XSS in search and GET parameters',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
    remediationAdvice: [
      'Sanitize all user inputs — use output encoding appropriate to context (HTML, JavaScript, URL, CSS)',
      'Implement Content Security Policy (CSP) with strict-src attribute — blocks inline scripts and eval-based attacks',
      'Use HTTPOnly flag on session cookies — prevents JS access, mitigating XSS session hijacking',
      'Apply same-origin policy and disable third-party cookies where possible',
    ],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "<script>alert(1)</script>";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();

      for (const testPayload of ["<script>alert(1)</script>", "javascript:alert(1)"] as const) {
        if (body.includes(testPayload)) {
          result.status = 'failed';
          result.evidence = `XSS payload echoed in page response — reflected XSS confirmed`;
          result.stepsToReproduce.push(`1. Navigate to ${url}`);
          result.stepsToReproduce.push(`2. Enter payload "<script>alert(1)</script>" into search box`);
          result.stepsToReproduce.push(`3. Submit form — observe payload echoed in DOM`);
          return result;
        }
      }

      return result;
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

import { Page } from '@playwright/test';

export interface BrokenAuthResult {
  vulnType: 'A02-Broken-Auth';
  severity: 'high';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
  remediationAdvice: Array<string>;
}

export async function testSessionHijacking(page: Page, url: string): Promise<BrokenAuthResult> {
  const result: BrokenAuthResult = {
    vulnType: 'A02-Broken-Auth',
    severity: 'high',
    description: 'Detect session hijacking via cookie transmission without HTTPS',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
    remediationAdvice: [
      'Always set Secure flag on session cookies — ensures cookies only transmitted over HTTPS',
      'Enable HttpOnly flag on session cookies — prevents JavaScript access via Document.cookie',
      'Implement SameSite=Strict or SameSite=Lax — blocks cross-site CSRF and reduces session theft attack surface',
      'Use short session timeouts and refresh tokens — limits window for stolen token misuse',
    ],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const loginForm = await page.locator('form[method="POST"], button[type="submit"]');
    if (loginForm.count() > 0) {
      await loginForm.fill({ username: 'admin', password: 'test' });
      await loginForm.press('Enter');
      const cookies = await page.context().cookies();
      for (const cookie of cookies) {
        if (/session|auth|token/.test(cookie.name.toLowerCase())) {
          if (cookie.secure === false) {
            result.status = 'failed';
            result.evidence = `Session cookie '${cookie.name}' transmitted without Secure flag — vulnerable to HTTPS downgrade attacks`;
            result.stepsToReproduce.push(`1. Navigate to ${url}`);
            result.stepsToReproduce.push(`2. Submit login form with credentials`);
            result.stepsToReproduce.push(`3. Inspect network traffic for cookie transmission`);
            result.stepsToReproduce.push(`4. Observe non-HTTPS cookie transmission — session hijacking possible`);
          }
        }
      }
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

import { Page } from '@playwright/test';

export interface BrokenAccessResult {
  vulnType: 'A05-Broken-Access';
  severity: 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce: Array<string>;
  remediationAdvice: Array<string>;
}

export async function testIDOR(page: Page, url: string): Promise<BrokenAccessResult> {
  const result: BrokenAccessResult = {
    vulnType: 'A05-Broken-Access',
    severity: 'critical',
    description: 'Detect IDOR vulnerability by modifying IDs in URLs',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
    remediationAdvice: [
      'Validate authorization on every protected endpoint — never rely solely on URL parameters',
      'Implement role-based access control (RBAC) — explicitly check current user\'s permissions vs required level',
      'Use object-level authorization — verify the current user owns the resource before serving it',
      'Apply default-deny policy — any request without explicit permission is rejected',
    ],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const profileEndpoint = await page.locator('a[href*="profile"], a[href*="user"]');
    if (profileEndpoint.count() > 0) {
      const originalProfileUrl = await page.evaluate(() => {
        const link = document.querySelector('a[href*="profile"], a[href*="user"]') as HTMLAnchorElement;
        return link?.href ?? '';
      });

      const modifiedProfileUrl = originalProfileUrl.replace(/\d+/, '9999');
      await page.goto(modifiedProfileUrl, { waitUntil: 'networkidle' });
      const profileData = await page.content();

      if (/admin|root|superuser/.test(profileData.toLowerCase())) {
        result.status = 'failed';
        result.evidence = `IDOR confirmed — accessing /profile/9999 returned admin/root profile. Privilege escalation possible.`;
        result.stepsToReproduce.push(`1. Navigate to ${originalProfileUrl}`);
        result.stepsToReproduce.push(`2. Change URL parameter from :id/1 to :id/9999`);
        result.stepsToReproduce.push(`3. Observe admin/root user profile returned — IDOR vulnerability confirmed`);
      }

      return result;
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

