import { chromium, Page } from '@playwright/test';
import { PentestPipeline, PipelineStage, StageOutput } from './pipeline';

export interface OrchestratorResult {
  scanId: string;
  targetUrl: string;
  startTime: Date;
  endTime: Date;
  results: Array<{
    stageName: string;
    stageResult: string;
    vulnType?: string;
    severity?: 'low' | 'medium' | 'high' | 'critical';
    status: 'passed' | 'failed';
    evidence?: string;
    stepsToReproduce?: Array<string>;
    remediationAdvice?: Array<string>;
  }>;
  summary: {
    totalVulnerabilities: number;
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
}

async function scanRecon(page: Page, url: string): Promise<any> {
  await page.goto(url, { waitUntil: 'networkidle' });

  const title = await page.title();
  let viewport = 'N/A';
  try {
    const meta = await page.locator('meta[name="viewport"]').getAttribute('content');
    if (meta) viewport = meta;
  } catch {}

  let description = 'N/A';
  try {
    const meta = await page.locator('meta[name="description"]').getAttribute('content');
    if (meta) description = meta;
  } catch {}

  let favicon: boolean = false;
  try {
    favicon = await page.locator('link[rel="icon"], link[rel="shortcut icon"]').count() > 0;
  } catch {}

  const jsFiles: string[] = [];
  try {
    const srcs = await page.evaluate(() => {
      return Array.from(document.scripts)
        .map((s: any) => s.src)
        .filter(Boolean);
    });
    jsFiles.push(...srcs);
  } catch {}

  let techStack: string[] = [];
  for (const src of jsFiles) {
    if (src.includes('react')) techStack.push('React');
    if (src.includes('vue')) techStack.push('Vue.js');
    if (src.includes('angular')) techStack.push('Angular');
    if (src.includes('ember')) techStack.push('Ember');
  }

  let apiEndpoints: Array<{path: string; method: 'GET' | 'POST'}> = [];
  try {
    const html = await page.content();
    if (html.includes('/api')) apiEndpoints.push({ path: '/api', method: 'GET' });
    if (html.includes('/graphql')) apiEndpoints.push({ path: '/graphql', method: 'POST' });
  } catch {}

  return {
    url,
    title,
    viewport,
    description,
    favicon,
    techStackDetected: techStack,
    endpoints: apiEndpoints,
  };
}

async function runVulnTests(page: Page, url: string): Promise<any[]> {
  const results: VulnResult[] = [];
  results.push(await testSQLi(page, url));
  results.push(await testReflectedXSS(page, url));
  results.push(await testSessionHijacking(page, url));
  results.push(await testIDOR(page, url));
  return results;
}

interface VulnResult {
  vulnType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce?: Array<string>;
  remediationAdvice?: Array<string>;
}

export async function orchestrate(
  url: string,
  stageOutput?: Record<string, any>
): Promise<OrchestratorResult> {
  const scanId = Date.now().toString();
  const startTime = new Date();

  const browser = await chromium.launch({ headless: false });
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);

  const pipeline = new PentestPipeline();

  // Recon stage
  pipeline.addStage({
    name: 'Recon',
    description: 'Reconnaissance and discovery phase',
    testFn: async () => {
      return await scanRecon(page, url);
    },
  });

  // Vulnerability Scan stage — runs all OWASP TOP 10 tests
  pipeline.addStage({
    name: 'Vuln Scan',
    description: 'OWASP TOP 10 vulnerability scanning',
    testFn: async () => {
      return await runVulnTests(page, url);
    },
  });

  // Execute stages and collect machine-readable outputs for pipeline chaining
  const results: Array<{
    stageName: string;
    stageResult: string;
    vulnType?: string;
    severity?: 'low' | 'medium' | 'high' | 'critical';
    status: 'passed' | 'failed';
    evidence?: string;
    stepsToReproduce?: Array<string>;
    remediationAdvice?: Array<string>;
  }> = [];

  for (const stage of pipeline.stages) {
    try {
      const result = await pipeline.executeStage(stage, page, url);
      results.push({
        stageName: stage.name,
        stageResult: JSON.stringify(result),
        vulnType: '',
        severity: 'low',
        status: 'passed',
        evidence: '',
        stepsToReproduce: [],
        remediationAdvice: [],
      });
    } catch (error) {
      results.push({
        stageName: stage.name,
        stageResult: `Error: ${String(error)}`,
        vulnType: '',
        severity: 'low',
        status: 'failed',
        evidence: String(error),
        stepsToReproduce: [],
        remediationAdvice: [],
      });
    }
  }

  const endTime = new Date();

  await browser.close();

  // Aggregate summary from results
  const summary = {
    totalVulnerabilities: results.filter((r: any) => r.status === 'failed').length,
    critical: 0,
    high: 0,
    medium: 0,
    low: 0,
  };

  results.forEach((r: any) => {
    if (r.severity && !['low'].includes(r.severity)) {
      summary[r.severity]++;
    }
  });

  return {
    scanId,
    targetUrl: url,
    startTime,
    endTime,
    results,
    summary,
  };
}

import { Page } from '@playwright/test';
import yaml from 'yaml';

export interface PipelineStage {
  name: string;
  description: string;
  testFn: (page: Page, url: string) => Promise<any>;
}

export type TestFn = (page: Page, url: string) => Promise<any>;

// Stage output for machine-readable pipeline chaining
export interface StageOutput<T = any> {
  stage: string;
  url: string;
  timestamp: Date;
  results?: T;
}

export class PentestPipeline {
  private stages: PipelineStage[] = [];
  private callbacks = new Array<(stage: PipelineStage, stageResult: any) => void>();

  addStage(stage: PipelineStage): void {
    this.stages.push(stage);
  }

  registerCallback(callback: (stage: PipelineStage, stageResult: any) => void): void {
    this.callbacks.push(callback);
  }

  private async executeStage(
    stage: PipelineStage,
    page: Page,
    url: string
  ): Promise<any> {
    const result = await stage.testFn(page, url);
    for (const callback of this.callbacks) {
      callback(stage, result);
    }
    return result;
  }

  async run(
    page: Page,
    url: string
  ): Promise<StageOutput> {
    const results = [];
    const startTime = new Date();

    for (const stage of this.stages) {
      try {
        const result = await this.executeStage(stage, page, url);
        results.push({
          stageName: stage.name,
          stageResult: JSON.stringify(result),
          timestamp: new Date().toISOString(),
        });
      } catch (error) {
        results.push({
          stageName: stage.name,
          stageResult: `Error: ${String(error)}`,
          timestamp: new Date().toISOString(),
        });
      }
    }

    const output = {
      stage: 'pipeline',
      url: url,
      timestamp: startTime.toISOString(),
      results: results.map((r: any) => ({
        ...r,
        stageName: r.stageName as string,
      })),
    };

    return output;
  }
}

