export async function exploitSQLi(page: Page, url: string): Promise<ExploitResult> {
  const result: ExploitResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Deliver malicious SQL payload via UNION-based injection',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "' UNION SELECT password FROM users-- ";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();

      if (/password/.test(body)) {
        result.status = 'failed';
        result.evidence = `SQL injection successful — extracted user passwords via UNION-based query. Data exfiltration confirmed.`;
        result.stepsToReproduce.push(`1. Navigate to ${url}`);
        result.stepsToReproduce.push(`2. Enter payload "' UNION SELECT password FROM users-- "`);
        result.stepsToReproduce.push(`3. Observe password column echoed in response — SQLi exploit successful`);
      }

      return result;
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

